// BraveBrand Team: the home.bravebrand.com team sheet, rebuilt as a Buzz page.
// Prebuilt API v1 module (generated by tools/build.py; edit the template).
// Hiring creates the employee in the selected community with agents.port, using
// the card read live from the member's tier on home.bravebrand.com.
export const inject = ["react", "pages", "agents", "host"];

const HOME = "https://home.bravebrand.com";
const ASSETS = "https://cdn.jsdelivr.net/gh/lukesbrave/bravebrand-buzz-team@b75b28950e18c347460c213bf5ef2bbac05bcf35/assets";
const CSS = "\n  \n  /* Figma palette: ink #16314c, sky #bbdcef, hired green #15bd58,\n     label gray #6f6f6f, empty-dot gray #c6c6c6. Crew art carries true\n     alpha (tools/matte-loops.sh) - no blend modes needed. */\n  .bb-root{--ink:#16314c;--sky:#bbdcef;--green:#15bd58;--gray60:#6f6f6f;\n    --gray30:#c6c6c6}\n  *{box-sizing:border-box}\n  .bb-root{position:relative;height:100%;overflow:hidden;container:bb/inline-size;margin:0;background:#fff;color:var(--ink);\n    font-family:\"Teachers\",\"Helvetica Neue\",Arial,sans-serif}\n  .labelfont{font-family:\"TXC Pearl\",\"Teachers\",sans-serif;font-weight:400;\n    text-transform:uppercase;letter-spacing:.02em}\n  img,.anim{display:block}\n  .blend{mix-blend-mode:multiply}\n  button{font-family:inherit}\n\n  /* ---------- header: one-viewport hero (Luke, 2026-08-30) ---------- */\n  .sheet{max-width:1728px;margin:0 auto;padding:0}\n  /* desktop title lives beside the house (.sidetitle); this one is mobile's */\n  h1{display:none;margin:0;text-align:center;font-weight:400;color:var(--ink);\n    font-size:clamp(34px,4.2vw,64px);line-height:1}\n  /* desktop moves the subheadline under the house (see #plaque);\n     mobile keeps it up top */\n  #intro{display:none;margin:12px auto 0;text-align:center;font-size:17px;\n    line-height:1.55;color:var(--gray60);max-width:560px}\n  /* mobile-only, like h1/#intro; desktop's pulse is the chip on the house */\n  #pulse{display:none;margin:6px auto 0;text-align:center;font-size:14px;\n    font-weight:600;color:var(--ink);min-height:20px}\n  #pulse:empty{display:none}\n\n  /* ---------- the hiring track: one meter (Luke, 2026-08-30) ----------\n     Count left, next hire right, green fill on a sky rail. The track is\n     pure distance now - action lives on the cards, reward in the house. */\n  #progress{margin:0;padding:0;width:100%}\n  .trackrow{display:flex;align-items:baseline;justify-content:space-between;\n    margin:0 0 8px}\n  #trackcount{font-size:14px;font-weight:600;color:var(--ink);\n    font-variant-numeric:tabular-nums}\n  #tracknext{font-size:12px;font-weight:600;color:var(--gray60);\n    text-transform:uppercase;letter-spacing:.06em}\n  .meter{height:10px;border-radius:99px;background:var(--sky);overflow:hidden}\n  .meterfill{height:100%;width:0;border-radius:99px;background:var(--green);\n    transition:width .9s ease .15s}\n\n  /* ---------- the board: full-height house with the title at its side,\n     crew shelf beneath (Luke, 2026-08-30) ---------- */\n  .board{width:100%;max-width:1728px;margin:0 auto}\n  .center{height:calc(var(--bbvh,100vh) - 104px);min-height:560px;padding:30px 24px 26px;\n    display:flex;align-items:center;justify-content:center;\n    gap:clamp(24px,4.5vw,80px);width:100%}\n  .housewrap{height:100%;display:flex;justify-content:center;\n    position:relative}\n  #house{position:relative;height:100%;aspect-ratio:3/4}\n  #house img{width:100%;height:100%;object-fit:contain}\n  /* crew tops out level with the house; the meter sits on the floor.\n     The column and the figures scale with the screen so a big monitor\n     gets a big team, not a narrow strip (Luke, 2026-08-31) */\n  .rightcol{height:100%;display:flex;flex-direction:column;\n    justify-content:flex-start;gap:20px;\n    flex:0 1 clamp(660px,46vw,920px);min-width:0}\n  /* crew floats centred in the space above the meter: equal air above and\n     below it, meter still on the floor (Luke, 2026-08-31) */\n  .crew{margin:auto 0}\n  /* desktop went minimalist (Luke, 2026-08-30): the side title + intro are\n     retired; the header carries the name, the info-i carries the copy */\n  .aside{display:none}\n\n  /* ---------- chrome: slim header + footer ---------- */\n  #topbar{display:flex;align-items:center;justify-content:space-between;\n    height:58px;padding:0 24px;border-bottom:1px solid rgba(22,49,76,.08);\n    position:relative}\n  /* public invitation lives centred in the header (Luke, 2026-08-31) */\n  #headinvite{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);\n    background:var(--green);color:#fff;padding:7px 16px;border-radius:99px;\n    font-size:13px;font-weight:600;text-decoration:none;white-space:nowrap;\n    transition:filter .18s ease}\n  #headinvite:hover,#headinvite:focus-visible{filter:brightness(1.07)}\n  #headinvite[hidden]{display:none}\n  /* wordmark + surface text match playground.bravebrand.com exactly:\n     bb-logo image at 20px, Inter Tight 11px caps at .15em, 50% black */\n  .brandline{display:flex;align-items:center;gap:10px;margin:0}\n  .brandline .wordmark{height:20px;width:auto;display:block}\n  .brandline .pagename{font-family:\"Inter Tight\",\"Teachers\",sans-serif;\n    font-size:11px;font-weight:600;color:rgba(0,0,0,.5);\n    text-transform:uppercase;letter-spacing:.15em;white-space:nowrap}\n  #info{position:relative}\n  #infobtn{width:28px;height:28px;border-radius:99px;\n    border:1.5px solid var(--gray30);background:none;color:var(--gray60);\n    font-size:14px;font-weight:600;line-height:1;cursor:pointer;\n    font-family:Georgia,serif;font-style:italic}\n  #infobtn:hover,#infobtn:focus-visible{border-color:var(--ink);color:var(--ink)}\n  #infotip{position:absolute;top:38px;right:0;width:300px;margin:0;\n    background:var(--ink);color:#fff;border-radius:10px;padding:14px 16px;\n    font-size:13.5px;line-height:1.55;display:none;z-index:60;text-align:left;\n    box-shadow:0 10px 28px rgba(22,49,76,.25)}\n  #info:hover #infotip,#info:focus-within #infotip,\n  #info.open #infotip{display:block}\n  #foot{height:46px;display:flex;align-items:center;justify-content:center;\n    border-top:1px solid rgba(22,49,76,.08);font-size:12.5px;\n    color:var(--gray60);background:#fff;position:relative;z-index:5}\n  /* team pulse floats above the roof peak as a chip in hired-green; it only\n     speaks on news - hire moment, fresh training, unlock (Luke, 2026-08-30) */\n  #pulse2{position:absolute;top:0;left:50%;transform:translate(-50%,-65%);\n    z-index:3;background:var(--green);color:#fff;padding:7px 16px;\n    border-radius:99px;font-size:13.5px;font-weight:600;white-space:nowrap;\n    box-shadow:0 2px 8px rgba(22,49,76,.18)}\n  #pulse2:empty{display:none}\n  #pulse a,#pulse2 a{color:inherit;text-decoration:none}\n  #pulse a:hover,#pulse2 a:hover,#pulse a:focus-visible,\n  #pulse2 a:focus-visible{text-decoration:underline}\n  .room{position:absolute;inset:0;width:100%;height:100%;opacity:0;\n    transition:opacity .5s ease;pointer-events:none}\n  .room.on{opacity:1}\n  /* no text under the house (Luke, 2026-08-30) - the elements stay for the\n     JS plaque machinery but never render; one-liners live in the spotlight */\n  #plaque,#deed{display:none}\n\n  /* figures and row gaps scale with width but are CAPPED BY HEIGHT\n     (30vh-140px ~ three rows + badges + meter inside the board), so\n     wide-but-short screens never clip the meter (Luke, 2026-08-31) */\n  .crew{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));\n    gap:clamp(12px,min(1.9vw,2.5vh),36px) 12px;justify-items:center;\n    width:100%}\n  .seat{width:100%;max-width:clamp(152px,min(10.5vw,33vh - 138px),205px);\n    cursor:pointer;\n    border:0;background:none;padding:0;color:inherit;display:block}\n  .seat:focus-visible{outline:2px solid var(--ink);outline-offset:6px;\n    border-radius:12px}\n  /* stills + loops share one true-square framing (2048x2048 baseplates) */\n  .fig{display:block;position:relative;width:100%;aspect-ratio:1/1}\n  .fig img,.fig .anim{position:absolute;inset:0;width:100%;height:100%;\n    object-fit:contain;transform:scale(var(--figscale,1));\n    transform-origin:50% 88%}   /* grow from the feet, not the middle */\n  /* poster = the loop's own first frame, so the swap is an INSTANT flip on\n     the .anim's first presented frame - a crossfade would dip both layers\n     to half-opacity and flash the white page through the figure */\n  .fig .anim{opacity:0}\n  .fig.playing .anim{opacity:1}\n  /* the still hides two frames AFTER the .anim reveals ('settled'), so a\n     lagging .anim layer shows the still behind it, never the white page */\n  .fig.settled img{opacity:0}\n  .seat .badge{margin:8px auto 0;height:34px;min-width:96px;\n    padding:0 12px;font-size:11.5px}\n  .seat .badge img{width:15px;height:15px}\n  /* one-liners live in the spotlight on desktop; on mobile the role and\n     one-liner sit between the figure and the button */\n  .srole,.sdesc{display:none}\n\n  /* step badge - Figma 120x44, ink, Roboto Bold 12; hired flips green */\n  .badge{min-width:120px;height:44px;padding:0 18px;border-radius:8px;\n    background:var(--ink);color:#fff;display:flex;align-items:center;\n    justify-content:center;gap:5px;font-family:\"Roboto\",sans-serif;\n    font-weight:700;font-size:12px;position:relative;width:max-content}\n  .badge .btext{display:flex;align-items:center;gap:5px}\n  .badge img{width:18px;height:18px}\n  .badge{transition:transform .18s ease,box-shadow .18s ease}\n  .seat:hover .badge{transform:translateY(-2px);\n    box-shadow:0 8px 18px rgba(22,49,76,.25)}\n  .badge:active{transform:scale(.97)}\n  .badge.hired{background:var(--green)}\n  .badge.act{background:var(--sky);color:var(--ink)}\n  .badge.soon{opacity:.55}\n  .badge .freshdot{position:absolute;top:-4px;right:-4px;width:12px;height:12px;\n    border-radius:99px;background:#f5a623;border:2px solid #fff;display:none}\n  .badge.fresh .freshdot{display:block}\n\n  /* ---------- agent spotlight ---------- */\n  #spotlight{position:absolute;inset:0;z-index:70;display:none}\n  #spotlight.open{display:block}\n  .scrim{position:absolute;inset:0;background:rgba(0,0,0,.5);\n    backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}\n  .panel{position:relative;height:100%;overflow-y:auto;overscroll-behavior:contain;\n    display:flex;padding:40px 24px;color:#fff}\n  .spot-surface{position:relative;display:grid;grid-template-columns:38% minmax(0,1fr);\n    width:min(1080px,100%);margin:auto;border:1px solid #ffffff24;border-radius:28px;\n    background:#102337;box-shadow:0 24px 90px #0006;overflow:hidden;flex-shrink:0}\n  .spot-identity{display:flex;flex-direction:column;align-items:center;justify-content:center;\n    padding:42px 28px;background:linear-gradient(145deg,#ffffff09,transparent);\n    border-right:1px solid #ffffff18;text-align:center;min-width:0}\n  .spot-team{margin:0 0 18px;font-size:14px;line-height:1.4;font-weight:600;color:var(--sky)}\n  .spot-card{width:min(100%,290px);aspect-ratio:1/1;position:relative;flex-shrink:0;\n    background:radial-gradient(ellipse,#bbdcef18 0%,transparent 68%)}\n  .spot-card img,.spot-card .anim{position:absolute;inset:0;width:100%;height:100%;\n    object-fit:contain;transform:scale(var(--figscale,1));transform-origin:50% 88%}\n  .spot-card .anim{opacity:0}\n  .spot-card.playing .anim{opacity:1}\n  .spot-card.settled img{opacity:0}\n  .spot-eyebrow{margin:22px 0 14px;font-size:12px;font-weight:600;\n    letter-spacing:.18em;text-transform:uppercase;color:var(--sky)}\n  .spot-name{margin:0;font-weight:400;font-size:clamp(38px,4vw,56px);line-height:1.02;color:#fff}\n  .spot-content{min-width:0;padding:64px 40px 36px;display:flex;flex-direction:column;gap:26px}\n  .spot-desc{margin:0;font-weight:600;font-size:20px;line-height:1.5;color:#edf3f8}\n  .spot-stats{display:grid;gap:10px;margin:0;text-align:left}\n  .spot-stats:empty{display:none}\n  .spot-stats>div{display:grid;grid-template-columns:82px minmax(0,1fr);gap:14px;\n    padding:16px;border:1px solid #ffffff14;border-radius:12px;background:#ffffff04;align-items:baseline}\n  .spot-stats dt{font-size:11px;font-weight:600;letter-spacing:.1em;\n    text-transform:uppercase;color:var(--sky);white-space:nowrap}\n  .spot-stats dd{margin:0;font-size:17px;line-height:1.4;color:#fff;font-weight:600}\n  .spot-act{display:flex;flex-direction:column;align-items:flex-start;gap:12px;\n    padding-top:24px;border-top:1px solid #ffffff18}\n  .cta{background:var(--sky);color:var(--ink);border:0;border-radius:999px;\n    padding:16px 30px;font-family:\"Roboto\",sans-serif;font-weight:700;font-size:18px;\n    cursor:pointer;text-decoration:none;display:inline-block;text-align:center;\n    transition:transform .18s ease,box-shadow .18s ease,filter .18s ease}\n  .cta:hover{transform:translateY(-2px);filter:brightness(1.05);box-shadow:0 10px 24px #0004}\n  .cta:active{transform:translateY(0)}\n  .cta:disabled{cursor:not-allowed;opacity:.5;transform:none;box-shadow:none}\n  .spot-tiny{font-size:14px;line-height:1.5;color:#c3cfda}\n  .spot-tiny a{color:var(--sky)}\n  .update-link{background:none;border:0;color:var(--sky);text-decoration:underline;\n    text-underline-offset:3px;cursor:pointer;font:inherit;font-size:14px;padding:10px 0;min-height:44px;text-align:left}\n  .fresh-line{font-size:13px;font-weight:600;color:#ffce73}\n  .spot-soon{font-size:14px;color:#c3cfda}\n  .spot-close{position:absolute;top:16px;right:16px;width:40px;height:40px;\n    border:1px solid #ffffff24;border-radius:50%;background:#183047;color:#dce9f3;\n    font-size:28px;line-height:1;cursor:pointer;z-index:2}\n  .spot-close:hover{background:#28445e;color:#fff}\n  #spotlight :is(button,a,summary,textarea):focus-visible{outline:3px solid var(--sky);outline-offset:4px}\n  #spotlight textarea:focus-visible{outline-offset:2px}\n  .update-steps,.update-intro{display:none}\n  #spotlight.updating .spot-team,#spotlight.updating .spot-card,#spotlight.updating .spot-desc,#spotlight.updating .spot-stats{display:none}\n  #spotlight.updating .spot-surface{grid-template-columns:32% minmax(0,1fr)}\n  #spotlight.updating .spot-identity{align-items:flex-start;justify-content:flex-start;text-align:left;padding:42px 30px}\n  #spotlight.updating .spot-eyebrow{margin:0 0 16px}\n  #spotlight.updating .spot-name{font-size:38px}\n  #spotlight.updating .update-intro{display:block;margin:18px 0 0;font-size:15px;line-height:1.5;color:#c3cfda}\n  #spotlight.updating .spot-content{padding:48px 40px 32px;min-height:570px}\n  #spotlight.updating .spot-act{border:0;padding:0;gap:18px;align-items:stretch}\n  #spotlight.updating .update-steps{display:grid;gap:20px;padding:0;margin:32px 0 0;list-style:none;width:100%}\n  .update-steps li{display:flex;align-items:center;gap:12px;font-size:15px;color:#bdcbd7}\n  .step-number{display:grid;place-items:center;width:30px;height:30px;flex-shrink:0;\n    border-radius:50%;border:1px solid #ffffff35;font-size:13px}\n  .update-steps [aria-current=\"step\"]{color:#fff;font-weight:600}\n  .update-steps [aria-current=\"step\"] .step-number{background:var(--sky);border-color:var(--sky);color:var(--ink)}\n  .update-stage{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--sky);font-weight:600;margin:0}\n  .update-heading{font:600 clamp(25px,2.4vw,30px)/1.15 \"Teachers\",sans-serif;margin:0;color:white}\n  .update-heading:focus{outline:none}\n  .update-copy{font-size:17px;line-height:1.5;margin:0;color:#e2eaf1}\n  .update-checklist{list-style:none;padding:0;margin:0;display:grid;gap:14px;counter-reset:tasks}\n  .update-checklist li{display:grid;grid-template-columns:24px 1fr;gap:10px;font-size:16px;line-height:1.5;color:#e2eaf1}\n  .update-checklist li:before{counter-increment:tasks;content:counter(tasks) \".\";color:var(--sky);font-weight:600}\n  .update-field{display:grid;gap:8px;font-size:14px;font-weight:600}\n  #spotlight textarea{width:100%;box-sizing:border-box;font:400 14px/1.5 \"Teachers\",sans-serif;\n    color:var(--ink);background:#f5f8fb;border:1px solid #a7b7c5;border-radius:10px;padding:14px;resize:vertical}\n  #spotlight textarea::placeholder{color:#536b7f;opacity:1}\n  .update-note{padding:15px 18px;background:#bbdcef0a;border:1px solid #bbdcef26;\n    border-radius:12px;font-size:15px;line-height:1.5;color:#d2dfea;margin:0}\n  .update-note strong{display:block;margin-bottom:4px;color:#fff}\n  .update-review summary{font-size:14px;color:var(--sky);cursor:pointer;padding:6px 0;min-height:32px}\n  .update-review textarea{margin-top:10px}\n  .release-notes{width:100%;border:1px solid #bbdcef30;border-radius:12px;background:#bbdcef08;text-align:left}\n  .release-notes>summary{position:relative;list-style:none;cursor:pointer;padding:14px 42px 14px 16px}\n  .release-notes>summary::-webkit-details-marker{display:none}\n  .release-notes>summary:after{content:'+';position:absolute;right:16px;top:12px;font-size:22px;color:var(--sky)}\n  .release-notes[open]>summary:after{content:'\u2212'}\n  .release-label{display:block;font-size:13px;font-weight:600;color:var(--sky)}\n  .release-summary{display:block;margin-top:5px;font-size:15px;line-height:1.45;color:#e2eaf1}\n  .release-body{display:grid;gap:18px;padding:4px 16px 18px;font-size:15px;line-height:1.5;color:#d2dfea}\n  .release-body h3,.release-body h4,.release-body p{margin:0}\n  .release-body h3,.release-body h4{font-size:15px;color:#fff;font-weight:600;margin-bottom:5px}\n  .release-title{font-size:13px;color:var(--sky)}\n  .release-notes.compact{background:none;border:0}\n  .release-notes.compact>summary{padding-left:0}\n  .release-notes.compact .release-body{padding-left:0;padding-right:0}\n  .update-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:4px}\n  .update-actions .cta{width:100%}\n  .update-actions [hidden]{display:none}\n  #spotlight .secondary{background:none;color:var(--sky);border:1px solid #bbdcef55;box-shadow:none}\n  #update-feedback{margin:0;font-size:14px;line-height:1.5;color:#ffda96}\n  #update-feedback:empty{display:none}\n  .update-footer{border-top:1px solid #ffffff18;padding-top:12px;margin-top:2px;\n    display:flex;align-items:center;justify-content:space-between;gap:16px}\n  .update-footer .spot-tiny{font-size:12px;text-align:right;max-width:280px}\n  @container bb (max-width:760px){\n    .panel{padding:16px 12px}\n    .spot-surface{grid-template-columns:1fr;border-radius:20px}\n    .spot-identity{padding:26px 24px;border-right:0;border-bottom:1px solid #ffffff18}\n    .spot-card{width:180px}\n    .spot-eyebrow{margin:12px 0}\n    .spot-name{font-size:38px;max-width:12ch}\n    .spot-content{padding:26px 22px;gap:22px}\n    .spot-desc{font-size:18px}\n    .spot-stats>div{grid-template-columns:68px minmax(0,1fr);padding:14px 12px;gap:10px}\n    .spot-stats dt{font-size:10px}\n    .spot-stats dd{font-size:16px}\n    .spot-act>.cta{width:100%}\n    #spotlight.updating .spot-surface{grid-template-columns:1fr}\n    #spotlight.updating .spot-identity{padding:26px 22px 20px}\n    #spotlight.updating .spot-name{font-size:32px;max-width:calc(100% - 28px)}\n    #spotlight.updating .spot-eyebrow{margin-bottom:12px}\n    #spotlight.updating .update-intro{display:none}\n    #spotlight.updating .update-steps{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:24px 0 0}\n    .update-steps li{flex-direction:column;gap:8px;text-align:center;font-size:12px;line-height:1.3}\n    #spotlight.updating .spot-content{padding:26px 22px 20px;min-height:0}\n    #spotlight.updating .spot-act{gap:18px}\n    .update-footer{align-items:flex-start}\n  }\n\n  #confetti{position:absolute;inset:0;pointer-events:none;z-index:90}\n\n  @media(prefers-reduced-motion:reduce){\n    .room{transition:none}\n    .meterfill{transition:none}\n    .cta,.badge{transition:none}\n    .cta:hover,.seat:hover .badge{transform:none}\n  }\n\n  /* ---------- mobile: no hover layer, tap goes straight to spotlight ---------- */\n  @container bb (max-width:1100px){\n    .sheet{padding:40px 16px 56px;display:block;height:auto;min-height:0}\n    /* big two-line title with air above it (Luke, 2026-08-30) */\n    h1{display:block;font-size:clamp(42px,11vw,58px);line-height:1.04;\n      max-width:16ch;margin:0 auto}\n    /* the mobile invitation is the #pulse line; the header stays clean */\n    #headinvite{display:none}\n    #intro{display:block}\n    /* the intro is on the page here, so the info-i has nothing to add */\n    #info{display:none}\n    #pulse{display:block}\n    #pulse:empty{display:none}\n    .board{display:block}\n    /* mobile keeps it simple: no house, no side title, just the crew */\n    .center{display:block;height:auto;min-height:0;padding:0}\n    .housewrap,.aside,#progress{display:none}\n    .seat{max-width:none}\n    .rightcol{display:block;height:auto}\n    /* single column, hire order top to bottom - clear the desktop grid\n       placements or the slot rules keep pairing seats into extra columns */\n    .crew{display:grid;grid-template-columns:minmax(0,1fr);gap:58px;\n      margin-top:38px}\n    /* the seat spans the screen so the copy can breathe; only the figure\n       stays capped */\n    .seat[data-slot]{grid-column:auto;grid-row:auto;margin:0 auto;\n      width:100%;max-width:460px}\n    .seat .fig{width:min(62vw,240px);margin:0 auto}\n    /* role names read as real headings on phones, not captions */\n    .srole{display:block;margin:14px auto 0;text-align:center;\n      font-size:clamp(26px,7vw,32px);line-height:1.1;color:var(--ink)}\n    /* one step below the page intro (17px): title > intro > role > desc */\n    .sdesc{display:block;margin:8px auto 4px;width:100%;\n      font-size:15px;line-height:1.55;color:var(--ink);text-align:center}\n    .seat .badge{height:54px;min-width:180px;font-size:16px;\n      border-radius:10px;margin-top:14px}\n    .badge img{width:20px;height:20px}\n  }\n\n  .bb-scroll{height:100%;overflow:auto}\n  .anim:not([src]){visibility:hidden}\n  #gate{display:flex;gap:8px;align-items:center}\n  #gate[hidden]{display:none}\n  #gate input{width:min(380px,42vw);height:34px;padding:0 12px;border-radius:99px;\n    border:1.5px solid var(--gray30);font:500 13px \"Teachers\",sans-serif;color:var(--ink)}\n  #gate input:focus{outline:none;border-color:var(--ink)}\n  #foot #changelink{border:0;background:none;padding:0;color:inherit;font:inherit;text-decoration:underline;cursor:pointer}\n  .spot-unlock{display:flex;flex-direction:column;align-items:flex-start;gap:12px;width:100%}\n  .spot-unlock input{width:100%;box-sizing:border-box;height:48px;padding:0 16px;border-radius:12px;\n    border:1px solid #a7b7c5;background:#f5f8fb;color:var(--ink);font:500 15px \"Teachers\",sans-serif}\n  .spot-unlock input:focus{outline:3px solid var(--sky);outline-offset:2px}\n  #gate button{height:34px;padding:0 16px;border:0;border-radius:99px;background:var(--green);\n    color:#fff;font:600 13px \"Teachers\",sans-serif;cursor:pointer}\n";
const FONTS = [["Teachers", "400 600", ""], ["Inter Tight", "600", ""], ["Roboto", "700", ""], ["TXC Pearl", "400", ""]];
